// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address nonOwner, uint256 value) public {
        vm.assume(nonOwner != c.owner());
        value = bound(value, 0, address(c).balance);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney(address(0), value) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
